import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers based on effect size and significance
    drivers = []
    candidates = []

    # Filter for clinical and copy_number features as potential drivers
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('clinical', 'copy_number'):
            # Use Welch's t-test p-value and effect size
            t_stat = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean()) / (
                feats.x[:, i].std() * np.sqrt(1/np.sum(feats.y==1) + 1/np.sum(feats.y==0)))
            p_val = 2 * (1 - stats.t.cdf(abs(t_stat), df=len(feats.y)-2))
            if p_val < 0.05 and abs(feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean()) > 0.1:
                candidates.append((fid, p_val, abs(feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean())))

    # Sort by significance and effect size
    candidates.sort(key=lambda x: (x[1], -x[2]))

    # Select top drivers
    for fid, _, _ in candidates[:MAX_DRIVERS]:
        drivers.append(fid)

    # If no drivers identified, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build columns and products
    columns = list(feats.ids)
    products = []
    loadings = {}

    # Add significant features to loadings (limit to 3)
    loading_count = 0
    for i, fid in enumerate(feats.ids):
        if loading_count >= 3:
            break
        if feats.types[i] in ('clinical', 'copy_number') and fid not in drivers:
            # Use mutual information for loadings
            mi = mutual_info_classif(feats.x[:, i].reshape(-1, 1), feats.y)[0]
            if mi > 0.01:  # threshold for inclusion
                loadings[fid] = mi
                loading_count += 1

    # Add interaction terms between top driver and other features (limit to 2)
    product_count = 0
    if drivers:
        top_driver = drivers[0]
        driver_idx = feats.column(top_driver)

        # Check correlations with top driver
        correlations = []
        for i, fid in enumerate(feats.ids):
            if fid != top_driver and fid not in drivers and product_count < 2:
                corr = np.corrcoef(feats.x[:, driver_idx], feats.x[:, i])[0, 1]
                if abs(corr) > 0.6:
                    correlations.append((fid, abs(corr)))

        # Sort by correlation strength
        correlations.sort(key=lambda x: x[1], reverse=True)

        # Add top correlations as products
        for fid, _ in correlations[:2]:
            products.append((top_driver, fid))
            product_count += 1

    # Limit total design terms to prevent overfitting
    total_terms = len(drivers) + len(columns) + len(products) + len(loadings)
    if total_terms > 12:
        # Reduce to minimal model
        if len(loadings) > 0:
            loadings = {list(loadings.keys())[0]: loadings[list(loadings.keys())[0]]}
        if len(products) > 0:
            products = [products[0]]
        if len(columns) > 10:
            columns = columns[:10]

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

